def gen(rng):
    def fmt(ts):
        return str(len(ts)) + '\n' + '\n'.join(f'{p} {dl}' for p, dl in ts)
    tests = [fmt([(5, 3)]), fmt([(10, 3), (8, 1), (6, 2)]), fmt([(1, 1), (1, 1)]), fmt([(1, 10000), (1, 10000), (1, 10000)]),
             fmt([(100, 0), (50, 0), (70, 0)]), fmt([(1, 10000), (10**9, 1)])]
    for n in (2, 3, 4, 5, 6, 7):
        for _ in range(4):
            tests.append(fmt([(rng.randint(1, 30), rng.randint(0, 10)) for _ in range(n)]))
    for n in (12, 30):
        tests.append(fmt([(rng.randint(1, 10**9), rng.randint(0, 10**4)) for _ in range(n)]))
    tests.append(fmt([(rng.randint(1, 10**9), rng.randint(0, 10**4)) for _ in range(2000)]))
    tests.append(fmt([(rng.randint(1, 10**9), rng.randint(0, 10**4)) for _ in range(100000)]))
    tests.append(fmt([(10**9, 10**4) for _ in range(100000)]))
    tests.append(fmt([(rng.randint(1, 100), rng.randint(5000, 10**4)) for _ in range(100000)]))
    tests.append(fmt([(rng.randint(1, 10**9), 0) for _ in range(100000)]))
    return tests
